describe('Responsive Font Size on Small Screens', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display readable font size on small screens without zooming', () => {
    // Set viewport to simulate small screen
    cy.viewport('iphone-x').then(() => {
      cy.intercept('GET', '/api/fonts').as('fetchFonts');
      cy.wait('@fetchFonts');
    });

    // Verify font size is set to a readable value
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="page-title"]').should('have.css', 'font-size', '16px');

    // Verify text is not blurry or pixelated
    cy.get('[data-testid="page-title"]').should('have.css', 'font-smooth', 'auto');

    // Verify text is still legible and not overflowing
    cy.get('[data-testid="page-title"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="page-title"]').should('not.contain', '...');

    // Verify responsive design adjusts font size on smaller screens
    cy.viewport('iphone-xs').then(() => {
      cy.get('[data-testid="page-title"]').should('have.css', 'font-size', '14px');
    });
  });

  it('should maintain readability when user zooms in on small screen', () => {
    // Set viewport to simulate small screen
    cy.viewport('iphone-x').then(() => {
      cy.intercept('GET', '/api/fonts').as('fetchFonts');
      cy.wait('@fetchFonts');
    });

    // Verify initial font size is readable
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="page-title"]').should('have.css', 'font-size', '16px');

    // Simulate user zooming in
    cy.get('[data-testid="page-title"]').trigger('wheel', { deltaY: -100 });

    // Verify font size does not increase beyond a reasonable limit
    cy.get('[data-testid="page-title"]').should('have.css', 'font-size', '18px');

    // Verify text remains legible and not overflowing
    cy.get('[data-testid="page-title"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="page-title"]').should('not.contain', '...');

    // Verify user can zoom out to original size
    cy.get('[data-testid="page-title"]').trigger('wheel', { deltaY: 100 });
    cy.get('[data-testid="page-title"]').should('have.css', 'font-size', '16px');
  });
});
